document.getElementById('qrGen').addEventListener('submit',function(e){e.preventDefault();const t=document.getElementById('qrText').value.trim(),r=document.getElementById('qrResult');if(!t){document.getElementById('qrText').classList.add('input-error');setTimeout(()=>{document.getElementById('qrText').classList.remove('input-error');},2e3);return}const c=document.createElement('canvas'),n=c.getContext('2d'),s=300;c.width=s;c.height=s;const u=`https://api.qrserver.com/v1/create-qr-code/?size=${s}x${s}&data=${encodeURIComponent(t)}`,o=new Image();o.crossOrigin='anonymous';o.onload=function(){n.drawImage(o,0,0,s,s);const e=s/2,i=s/2,l=32;n.fillStyle='#ffffff';n.beginPath();n.arc(e,i,l,0,Math.PI*2);n.fill();const a=48,h=e-a/2,p=i-a/2;n.strokeStyle='#4da6ff';n.lineWidth=3;n.beginPath();n.arc(e,i,20,0,Math.PI*2);n.stroke();n.strokeStyle='#4da6ff';n.lineWidth=2.5;n.lineCap='round';n.beginPath();n.moveTo(e-10,i-8);n.lineTo(e+10,i-8);n.stroke();n.beginPath();n.moveTo(e-10,i);n.lineTo(e+10,i);n.stroke();n.beginPath();n.moveTo(e-10,i+8);n.lineTo(e+6,i+8);n.stroke();r.innerHTML=`<img src="${c.toDataURL()}" alt="QR Code" style="max-width: 100%; border-radius: var(--radius); border: 1px solid var(--muted);">`},o.onerror=function(){r.innerHTML='<span style="color: #ff6b6b;">Ошибка генерации QR-кода</span>'},o.src=u});
